mapper.select:
select

mn.*
from Oa_Annual_Plan_Dtl mn
left join Oa_Annual_Plan ap on ap.id=mn.Ap_Id


    
        and ap.Te_Id = #{params.teId}
    
    
        and mn.Apd_Check_Type=#{params.apdCheckType}
    
    
        and ap.Ap_Year=#{params.apYear}
    
    
        and ap.State=#{params.state}
    
    
        and INSTR(ap.Create_Uname,#{params.createUname})
    

order by mn.Apd_Sort ASC
